127127The assumption by other answers that one needs to sort the data is not correct.The assumption by other answers that one needs to sort the data is not correct.The following code does not sort the entire array, but only 200-element segments of it, and thereby runs the fastest.The following code does not sort the entire array, but only 200-element segments of it, and thereby runs the fastest.Sorting only k-element sections completes the pre-processing in linear time, , rather than the  time needed to sort the entire array.Sorting only k-element sections completes the pre-processing in linear time, O(n)O(n), rather than the O(n.log(n))O(n.log(n)) time needed to sort the entire array.

Copy#include <algorithm>
#include <ctime>
#include <iostream>

int main() {
    int data[32768]; const int l = sizeof data / sizeof data[0];

    for (unsigned c = 0; c < l; ++c)
        data[c] = std::rand() % 256;

    // sort 200-element segments, not the whole array
    for (unsigned c = 0; c + 200 <= l; c += 200)
        std::sort(&data[c], &data[c + 200]);

    clock_t start = clock();
    long long sum = 0;

    for (unsigned i = 0; i < 100000; ++i) {
        for (unsigned c = 0; c < sizeof data / sizeof(int); ++c) {
            if (data[c] >= 128)
                sum += data[c];
        }
    }

    std::cout << static_cast<double>(clock() - start) / CLOCKS_PER_SEC << std::endl;
    std::cout << "sum = " << sum << std::endl;
}
